<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/catalog.php';send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';$productId=trim((string)($_GET['product_id']??''));$product=vendor_product($productId,$vendorId);if(!in_array($product['status'],['draft','changes_requested','rejected'],true)&&$method!=='GET')json_response(409,['success'=>false,'message'=>'Create a new product draft version before changing variants.']);if($method==='GET'){$stmt=$db->prepare('SELECT v.*,i.stock_quantity,i.reserved_quantity,i.low_stock_threshold FROM product_variants v JOIN inventory_levels i ON i.variant_id=v.id WHERE v.product_id=:product ORDER BY v.created_at');$stmt->execute(['product'=>$productId]);json_response(200,['success'=>true,'variants'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$name=trim((string)($body['name']??''));$sku=strtoupper(trim((string)($body['sku']??'')));if(mb_strlen($name)<1||mb_strlen($name)>180||!preg_match('/^[A-Z0-9._-]{2,100}$/',$sku))json_response(422,['success'=>false,'message'=>'Variant name and SKU are invalid.']);$id=uuid_string();$stock=max(0,(int)($body['stock']??0));$db->beginTransaction();try{$db->prepare('INSERT INTO product_variants (id,product_id,sku,name,attributes_json,price_adjustment,weight_grams,is_active,created_at,updated_at) VALUES (:id,:product,:sku,:name,:attributes,:price,:weight,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'product'=>$productId,'sku'=>$sku,'name'=>$name,'attributes'=>json_encode((array)($body['attributes']??[]),JSON_UNESCAPED_SLASHES),'price'=>round((float)($body['price_adjustment']??0),2),'weight'=>isset($body['weight_grams'])?max(1,(int)$body['weight_grams']):null]);$db->prepare('INSERT INTO inventory_levels (variant_id,stock_quantity,reserved_quantity,low_stock_threshold,updated_at) VALUES (:id,:stock,0,:threshold,UTC_TIMESTAMP())')->execute(['id'=>$id,'stock'=>$stock,'threshold'=>max(0,(int)($body['low_stock_threshold']??5))]);$db->prepare('INSERT INTO inventory_movements (variant_id,vendor_id,movement_type,quantity_delta,reserved_delta,stock_after,reserved_after,note,actor_type,actor_id,created_at) VALUES (:variant,:vendor,"initial",:qty,0,:qty,0,"Initial variant stock","vendor",:vendor,UTC_TIMESTAMP())')->execute(['variant'=>$id,'vendor'=>$vendorId,'qty'=>$stock]);$db->commit();json_response(201,['success'=>true,'message'=>'Variant created.','variant_id'=>$id]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}if($method==='PATCH'){$body=get_json_body();$id=trim((string)($body['variant_id']??''));$stmt=$db->prepare('UPDATE product_variants SET name=:name,attributes_json=:attributes,price_adjustment=:price,weight_grams=:weight,is_active=:active,updated_at=UTC_TIMESTAMP() WHERE id=:id AND product_id=:product');$stmt->execute(['name'=>trim((string)($body['name']??'')),'attributes'=>json_encode((array)($body['attributes']??[])),'price'=>round((float)($body['price_adjustment']??0),2),'weight'=>isset($body['weight_grams'])?max(1,(int)$body['weight_grams']):null,'active'=>!empty($body['is_active'])?1:0,'id'=>$id,'product'=>$productId]);json_response(200,['success'=>true,'message'=>'Variant updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
